/** One owner step through the API exactly as the review panel does it. */
async function step(
  r: { record: string; session: string },
  a: InstanceType<typeof WalletProviderAdapter>,
  over: Record<string, unknown> = {},
) {
  const auth = await api({
    action: "canary-authorize",
    session: r.session,
    record: r.record,
    trustedGesture: true,
  });
  expect(auth.status, JSON.stringify(auth.json)).toBe(200);
  const prep = await api({
    action: "canary-prepare",
    session: r.session,
    record: r.record,
    token: auth.json.token,
  });
  expect(prep.status, JSON.stringify(prep.json)).toBe(200);
  const write = (kind: string, ref: unknown, hash?: string) =>
    api({
      action: "canary-record",
      session: r.session,
      kind,
      ref,
      ...(hash ? { hash } : {}),
    }).then((x) => x.status === 200 && x.json.ok === true);
  // G14 follow-up F2: the server's confirmation and the durable "requested" record are the wallet adapter's OWN
  // calls of this API (through the page fetch it captured); the page hands over only the session.
  const result = await submitCanary(a, prep.json.preparation, {
    session: r.session,
    gesture: { trusted: true, at: Date.now() },
    persistNotRequested: (ref) => write("not-requested", ref),
    persistHash: (h, _a, ref) => write("hash", ref, h),
    persistLateHash: async (h, _a, ref) =>
      void (await write("late-hash", ref, h)),
    persistRejected: async (ref) => void (await write("rejected", ref)),
    ...over,
  });
  return { result, preparation: prep.json.preparation as Json };
}
const track = (r: { record: string; session: string }) =>
  api({ action: "canary-track", session: r.session, record: r.record });

describe("H3 + persistence on the runtime: conditional, attempt-bound, durable transitions", () => {
  it("restart: records, phases, consumed nonces, attempts and anchors are rebuilt; the old MAC key is gone; nothing is asked of a wallet", async () => {
    const rt = openCanaryRuntime({ dir });
    const { p, a } = wallet();
    const r = await review();
    const s = r.json as { record: string; session: string; review: string };
    const auth = await api({
      action: "canary-authorize",
      session: s.session,
      record: s.record,
      trustedGesture: true,
    });
    // (step() asks for its own token: the token above is superseded, never consumed.)
    const s1 = await step(s, a);
    expect(p.count("eth_sendTransaction")).toBe(1);
    const headBefore = rt.store.head();
    closeCanaryRuntime();
    // Restart (same directory): the old session and token are dead (new process key); nothing re-sends.
    const back = openCanaryRuntime({ dir });
    const recovery = back.recovery();
    expect(recovery.store).toMatchObject({ status: "READY", writable: true });
    expect(recovery.restoreProblem).toBeNull();
    const rec = recovery.records.find((x) => x.record === s.record)!;
    expect(rec.state).toBe("APPROVAL_SUBMITTED");
    expect(rec.attempts.map((x) => x.recovery)).toEqual(["SUBMITTED"]);
    expect(rec.audit.anchored).toBe(true);
    // The owner's held head from before the restart is an honest prefix.
    expect(back.verifyOwnerHead(headBefore)).toBeNull();
    expect(
      (
        await api({
          action: "canary-authorize",
          session: s.session,
          record: s.record,
          trustedGesture: true,
        })
      ).json.error,
    ).toBe("SESSION_INVALID");
    const r2 = await review();
    expect(r2.json.ready).toBe(false);
    expect(
      r2.json.checks.find((c: { id: string }) => c.id === "SINGLE_USE"),
    ).toMatchObject({ status: "FAIL", code: "APPROVAL_ALREADY_USED" });
    // The consumed nonce of the old token stays consumed after the restart (journaled), and its MAC is now FORGED.
    const reused = await api({
      action: "canary-prepare",
      session: r2.json.session,
      record: r2.json.record,
      token: auth.json.token,
    });
    expect(reused.json.error).toMatch(/FORGED|NOT_REVIEWED|GATE_CLOSED/);
    expect(
      CanaryDurableStore.inspect(dir)
        .entries.filter((e) => e.type === "NONCE")
        .map((e) => (e.data as { nonce: string }).nonce),
    ).toContain(s1.preparation.attempt);
    expect(p.count("eth_sendTransaction")).toBe(1);
  });
});

